reactiveclass Hub {
	statevars {
		Client clients[5];
		int clientCount;
	}

	msgsrv initial() {
		clientCount = 0;
	}

	msgsrv Register(Client ref) {
		if (clientCount < 5) {
			clients[clientCount] = ref;
			clientCount = clientCount + 1;
		}
	}

	msgsrv Ping() {
		sender.Pong();
	}
}

